// Cheap month-plan: read the menu of options + recent history, fill the 'planner'
// prompt, return one item with { system, user } for the Anthropic call. All Supabase
// reads happen here via this.helpers.httpRequest so PostgREST arrays don't fan out
// into multiple items. Mark replaces __SUPABASE_URL__ / YOUR_SUPABASE_SERVICE_ROLE_KEY
// on import (same find/replace as the other workflows).
const body = $('Webhook (fb-plan-period)').first().json.body || {};
const start_date = body.start_date || $now.toFormat('yyyy-LL-dd');
const days = Number(body.days || 30);
const SB = '__SUPABASE_URL__';
const KEY = 'YOUR_SUPABASE_SERVICE_ROLE_KEY';
const h = { apikey: KEY, Authorization: 'Bearer ' + KEY };
const subtopics = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_subtopics?status=eq.active&select=id,subtopic,pillar,last_used_at,times_used&order=last_used_at.asc.nullsfirst', headers: h, json: true });
const recent = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_content_plan?select=plan_date,pillar,archetype,subtopic_id&order=plan_date.desc&limit=60', headers: h, json: true });
const prompts = await this.helpers.httpRequest({ method: 'GET', url: SB + '/rest/v1/fb_messaging_prompts?is_active=eq.true&select=name,body', headers: h, json: true });
const byName = Object.fromEntries((prompts || []).map(p => [p.name, p.body]));
const pillars = ['storm','noise','energy','security','comfort','insurance','uv','value'];
const archetypes = ['myth-bust','secret-reveal','story','mistake-expose','seasonal','thought-leadership','community-cause','social-proof'];
const month = new Date(start_date + 'T00:00:00').toLocaleString('en-US', { month: 'long' });
const date_context = 'Window starts ' + start_date + ' (' + month + '). FL hurricane season runs Jun 1-Nov 30.';
let user = (byName['planner'] || '')
  .replaceAll('{{style_guide}}', byName['style_guide'] || '')
  .replaceAll('{{subtopics}}', JSON.stringify((subtopics || []).map(s => ({ id: s.id, subtopic: s.subtopic, pillar: s.pillar }))))
  .replaceAll('{{recent}}', JSON.stringify(recent || []))
  .replaceAll('{{date_context}}', date_context)
  .replaceAll('{{days}}', String(days))
  .replaceAll('{{start_date}}', start_date)
  .replaceAll('{{pillar_list}}', pillars.join(', '))
  .replaceAll('{{archetype_list}}', archetypes.join(', '));
return [{ json: { system: byName['style_guide'] || '', user, start_date, days } }];

// Tolerant JSON-array parse → validated rows for fb_content_plan (status 'planned').
let t = $json.content?.[0]?.text || '';
t = t.replace(/\`\`\`json|\`\`\`/g, '').trim();
let arr;
try { arr = JSON.parse(t); } catch (e) { const m = t.match(/\[[\s\S]*\]/); arr = m ? JSON.parse(m[0]) : []; }
if (!Array.isArray(arr)) arr = [];
const rows = arr
  .filter(r => r && r.date && r.pillar && r.archetype)
  .map(r => ({ plan_date: r.date, pillar: r.pillar, archetype: r.archetype, subtopic_id: r.subtopic_id || null, campaign: r.campaign || null, status: 'planned' }));
return [{ json: { rows, count: rows.length } }];
